"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9044],{62119:e=>{e.exports=JSON.parse('{"functions":[{"name":"Fetch","desc":"Creates the `Sound` with that name. If the name is not in the schema, a warning is printed and a blank `Sound`\\nnamed `VluxySF_Blank_Sound` is returned instead, so calling code never has to nil-check.\\n\\n:::info\\n- A preloaded or warmed sound is cloned from its template, which is faster than building it.\\n- A sound fetched without a parent is placed in `SoundService.UnattachedSounds`.\\n:::\\n\\n```lua\\nlocal mySound = VluxySF.Fetch(\\"MySound\\")\\nmySound.Volume = 0.3\\n\\nlocal echo = mySound.EchoSoundEffect\\nif echo then\\n\\techo.WetLevel = 1.3\\nend\\n\\nmySound:Play()\\n```","params":[{"name":"name","desc":"The name of the `Sound`.","lua_type":"string"},{"name":"parent","desc":"Parent of the `Sound`.","lua_type":"Instance?"},{"name":"preset","desc":"`Preset` to apply before parenting.","lua_type":"((Sound) -> ())?"}],"returns":[{"desc":"The new `Sound`.","lua_type":"Sound"}],"function_type":"static","tags":["RequiresSchema"],"source":{"line":93,"path":"lib/Api/Fetch.luau"}},{"name":"FetchStrict","desc":"The same as `Fetch`, but returns `nil` instead of a blank sound when the name is not in the schema.\\n\\n```lua\\nlocal mySound = VluxySF.FetchStrict(\\"MySound\\")\\n\\nif mySound then\\n\\tmySound:Play()\\nend\\n```","params":[{"name":"name","desc":"The name of the `Sound`.","lua_type":"string"},{"name":"parent","desc":"Parent of the `Sound`.","lua_type":"Instance?"},{"name":"preset","desc":"`Preset` to apply before parenting.","lua_type":"((Sound) -> ())?"}],"returns":[{"desc":"The new `Sound`, or `nil`.","lua_type":"Sound?"}],"function_type":"static","tags":["RequiresSchema"],"source":{"line":128,"path":"lib/Api/Fetch.luau"}},{"name":"FetchPlayOnce","desc":"Fetches a `Sound`, plays it once, and destroys it when it ends. Looping is turned off. If the name is not in the\\nschema, a warning is printed, nothing plays, and nothing is left behind.\\n\\n```lua\\nVluxySF.FetchPlayOnce(\\"MySound\\")\\n```","params":[{"name":"name","desc":"The name of the `Sound`.","lua_type":"string"},{"name":"parent","desc":"Parent of the `Sound`.","lua_type":"Instance?"},{"name":"preset","desc":"`Preset` to apply before parenting.","lua_type":"((Sound) -> ())?"},{"name":"waitOnLoad","desc":"Wait for the `Sound` to load before playing. The wait never blocks the caller.","lua_type":"boolean?"}],"returns":[{"desc":"Stops and destroys the `Sound` early.","lua_type":"() -> ()"}],"function_type":"static","tags":["RequiresSchema"],"source":{"line":162,"path":"lib/Api/Fetch.luau"}}],"properties":[],"types":[],"name":"VluxySF","desc":"Vluxy Sound Factory. Build your sounds in Studio once, then fetch any of them by name from the server or the\\nclient.\\n\\n```lua\\nlocal sound = VluxySF.Fetch(\\"MySound\\")\\nsound:Play()\\n```","realm":["Client","Server"],"source":{"line":66,"path":"lib/init.luau"}}')}}]);